import { createContext, useContext } from "solid-js";
export const UiContext = createContext();
export function useUi() { return useContext(UiContext); }
export function Panel(props) { useContext(UiContext); return props.children; }
export function Badge() { useContext(UiContext); return "b"; }
export const Ui = { Panel };
export class Reader { read() { return useContext(UiContext); } }
export const registry = { get current() { return useContext(UiContext); } };
const QuietContext = createContext(1);
export function Quiet(props) { useContext(QuietContext); return props.children; }
export function Plain(props) { return props.children; }
